namespace Intropy.Topology.Validation.Rules;

/// <summary>Rejects repeated service declarations and collisions with component app IDs.</summary>
internal sealed class ServiceUsageRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var component in context.Builder.Components)
        {
            foreach (var duplicate in component.ServiceCalls
                .GroupBy(service => service.AppId, StringComparer.Ordinal)
                .Where(group => group.Count() > 1))
            {
                yield return new TopologyDiagnostic(
                    DiagnosticSeverity.Error,
                    $"Component '{component.Name}' uses service '{duplicate.Key}' more than once.",
                    component.Name);
            }
        }

        var componentNames = context.Topology.Components
            .Select(component => component.Name)
            .ToHashSet(StringComparer.Ordinal);
        foreach (var service in context.Topology.Services.Where(service => componentNames.Contains(service.AppId)))
        {
            yield return new TopologyDiagnostic(
                DiagnosticSeverity.Error,
                $"Service app ID '{service.AppId}' collides with a topology component app ID.",
                service.AppId);
        }
    }
}

namespace Intropy.Topology;

/// <summary>How severe a topology diagnostic is.</summary>
public enum DiagnosticSeverity
{
    /// <summary>Suspicious but does not fail <see cref="SystemBuilder.Build"/>.</summary>
    Warning,

    /// <summary>Fails <see cref="SystemBuilder.Build"/>.</summary>
    Error,
}

/// <summary>One validation finding produced while building a topology.</summary>
/// <param name="Code">The stable rule code (e.g. <c>ITP101</c>).</param>
/// <param name="Severity">The finding's severity.</param>
/// <param name="Message">A human-readable description of the violation.</param>
/// <param name="Target">The component or resource name the finding is about, when applicable.</param>
public sealed record TopologyDiagnostic(
    string Code,
    DiagnosticSeverity Severity,
    string Message,
    string? Target);

using Intropy.Topology.Model;

namespace Intropy.Topology.Validation;

/// <summary>Runs every topology rule and collects the diagnostics.</summary>
internal static class TopologyRules
{
    // Retired codes — do not reuse. Enforced at compile time by the block builders:
    // ITP204 (trigger kind not allowed for the block kind), ITP205 (connector direction
    // not allowed for the block kind). No longer meaningful since triggers were replaced
    // by edges and activation/workload shape moved to the component scaffold: ITP201
    // (invalid cron on the trigger-era ScheduleTrigger — its successor for the schedule
    // *attribute* introduced by decision 0010 is ITP210), ITP202 (missing trigger),
    // ITP203 (multiple TriggeredBy calls).
    // Retired with the minimal model (full versions live on the full-topology branch):
    // ITP105/ITP106 (the original local connector-direction capability rules; deployed
    // transport capability is ITP211), ITP107 (unresolved connector — every connector now
    // declares its local transport), ITP501 (API provider — the API surface is not part of
    // the minimal model).
    private static readonly ITopologyRule[] Rules =
    [
        new Rules.DuplicateComponentNameRule(),
        new Rules.EmptySystemRule(),
        new Rules.DuplicatePortRule(),
        new Rules.DuplicateSubscriptionRule(),
        new Rules.TopicContractConflictRule(),
        new Rules.ConnectorConflictRule(),
        new Rules.DeployedTransportCapabilityRule(),
        new Rules.MissingRequiredOutputRule(),
        new Rules.MissingRequiredSubscriptionRule(),
        new Rules.ScheduleExpressionRule(),
        new Rules.UnconsumedTopicRule(),
        new Rules.UnproducedTopicRule(),
        new Rules.NoEdgesRule(),
        new Rules.PubSubConnectorNameCollisionRule(),
        new Rules.ServiceUsageRule(),
    ];

    public static IReadOnlyList<TopologyDiagnostic> Run(SystemBuilder builder, SystemTopology topology)
    {
        var context = new ValidationContext(builder, topology);
        return Rules.SelectMany(rule => rule.Evaluate(context)).ToArray();
    }
}

namespace Intropy.Topology.Test;

public sealed class ServiceTests
{
    private static readonly TopicRef<string> s_topic = TopicRef<string>.Define("orders", "created");
    private static readonly ServiceRef s_idempotency = ServiceRef.Define("idempotency-service");

    [Fact]
    public void Build_WithServiceUsage_ShouldMaterializeOrderedConsumerEdges()
    {
        // Arrange
        var builder = SystemBuilder.Create("orders");
        builder.AddExtractor("extractor").Publishes(s_topic).Uses(s_idempotency);
        builder.AddLoader("loader").Subscribes(s_topic).Uses(s_idempotency);

        // Act
        var topology = builder.Build();

        // Assert
        Assert.Equal(["idempotency-service"], topology.Components[0].Uses);
        var service = Assert.Single(topology.Services);
        Assert.Equal("idempotency-service", service.AppId);
        Assert.Equal(["extractor", "loader"], service.Consumers);
    }

    [Fact]
    public void Validate_WithRepeatedServiceUsage_ShouldReportAnError()
    {
        // Arrange
        var builder = SystemBuilder.Create("orders");
        builder.AddExtractor("extractor").Publishes(s_topic).Uses(s_idempotency).Uses(s_idempotency);
        builder.AddLoader("loader").Subscribes(s_topic);

        // Act
        var diagnostics = builder.Validate();

        // Assert
        Assert.Contains(diagnostics, diagnostic => diagnostic.Message.Contains("more than once", StringComparison.Ordinal));
    }

    [Fact]
    public void Validate_WithComponentAppIdMatchingService_ShouldReportAnError()
    {
        // Arrange
        var builder = SystemBuilder.Create("orders");
        builder.AddExtractor("idempotency-service").Publishes(s_topic).Uses(s_idempotency);
        builder.AddLoader("loader").Subscribes(s_topic);

        // Act
        var diagnostics = builder.Validate();

        // Assert
        Assert.Contains(diagnostics, diagnostic => diagnostic.Message.Contains("collides", StringComparison.Ordinal));
    }
}

